CREATE TYPE request_status AS ENUM ('DRAFT','PENDING_ASSIGNMENT'); CREATE TYPE case_origin AS ENUM ('COMPANY_REQUEST','INSTITUTIONAL_PROGRAM','HEALTH_ALERT','COMPLAINT'); CREATE TYPE case_status AS ENUM ('PENDING_REVIEW','PENDING_ASSIGNMENT','NO_ACTION','REFERRED','CLOSED'); CREATE TYPE priority_level AS ENUM ('LOW','MEDIUM','HIGH','URGENT'); CREATE TYPE request_document_type AS ENUM ('AUTHORIZATION_LETTER','SUPPORTING_DOCUMENT'); CREATE TYPE document_status AS ENUM ('PENDING','VALID','REJECTED','ARCHIVED'); CREATE TYPE health_alert_decision AS ENUM ('PENDING','PROCEEDS','NOT_PROCEEDS'); CREATE TYPE complaint_decision AS ENUM ('PENDING','PROCEEDS','NOT_PROCEEDS','REFERRED');
CREATE TABLE company_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE RESTRICT,establishment_id uuid NOT NULL REFERENCES establishments(id) ON DELETE RESTRICT,request_type varchar(80),reason text NOT NULL,observations text,status request_status NOT NULL DEFAULT 'DRAFT',submitted_at timestamptz,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(btrim(reason)<>''),CHECK((status='DRAFT' AND submitted_at IS NULL) OR (status='PENDING_ASSIGNMENT' AND submitted_at IS NOT NULL)));
CREATE TABLE request_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES company_requests(id) ON DELETE RESTRICT,document_type request_document_type NOT NULL,storage_path text NOT NULL,file_name varchar(300) NOT NULL,mime_type varchar(100) NOT NULL,size_bytes bigint NOT NULL,status document_status NOT NULL DEFAULT 'PENDING',uploaded_at timestamptz NOT NULL DEFAULT now(),validated_at timestamptz,deleted_at timestamptz,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(size_bytes>0 AND size_bytes<=5242880),CHECK(document_type<>'AUTHORIZATION_LETTER' OR mime_type IN('application/pdf','image/jpeg','image/png','image/webp')));
CREATE UNIQUE INDEX request_active_letter ON request_documents(request_id) WHERE document_type='AUTHORIZATION_LETTER' AND deleted_at IS NULL AND status IN('PENDING','VALID');
CREATE TABLE request_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES company_requests(id) ON DELETE RESTRICT,contact_id uuid NOT NULL REFERENCES contacts(id) ON DELETE RESTRICT,relationship_type contact_relationship_type NOT NULL,full_name_snapshot text NOT NULL,phone_snapshot text,email_snapshot text,is_primary boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,contact_id,relationship_type),CHECK(btrim(full_name_snapshot)<>''));
CREATE TABLE cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),origin case_origin NOT NULL,request_id uuid REFERENCES company_requests(id) ON DELETE RESTRICT,company_id uuid REFERENCES companies(id) ON DELETE RESTRICT,establishment_id uuid REFERENCES establishments(id) ON DELETE RESTRICT,priority priority_level NOT NULL DEFAULT 'MEDIUM',status case_status NOT NULL,closed_at timestamptz,closed_reason text,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id),CHECK((status IN('PENDING_REVIEW','PENDING_ASSIGNMENT') AND closed_at IS NULL) OR (status IN('NO_ACTION','REFERRED','CLOSED') AND closed_at IS NOT NULL)),CHECK(status NOT IN('NO_ACTION','REFERRED') OR (closed_reason IS NOT NULL AND btrim(closed_reason)<>'')));
CREATE TABLE institutional_program_cases(case_id uuid PRIMARY KEY REFERENCES cases(id) ON DELETE RESTRICT,program_reference varchar(200),planned_date date,reason text NOT NULL,observations text,CHECK(btrim(reason)<>''));
CREATE TABLE health_alerts(case_id uuid PRIMARY KEY REFERENCES cases(id) ON DELETE RESTRICT,alert_number varchar(120) NOT NULL UNIQUE,alert_date date NOT NULL,product_description text NOT NULL,description text NOT NULL,decision health_alert_decision NOT NULL DEFAULT 'PENDING',decided_at timestamptz,decided_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,decision_reason text,CHECK(btrim(product_description)<>'' AND btrim(description)<>''),CHECK((decision='PENDING' AND decided_at IS NULL AND decided_by_user_id IS NULL) OR (decision IN('PROCEEDS','NOT_PROCEEDS') AND decided_at IS NOT NULL AND decided_by_user_id IS NOT NULL)));
CREATE TABLE complaints(case_id uuid PRIMARY KEY REFERENCES cases(id) ON DELETE RESTRICT,complaint_type varchar(120) NOT NULL,received_at timestamptz NOT NULL,complainant_data jsonb,description text NOT NULL,decision complaint_decision NOT NULL DEFAULT 'PENDING',decided_at timestamptz,decided_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,referral_reason text,CHECK(btrim(complaint_type)<>'' AND btrim(description)<>''),CHECK((decision='PENDING' AND decided_at IS NULL AND decided_by_user_id IS NULL AND referral_reason IS NULL) OR (decision IN('PROCEEDS','NOT_PROCEEDS') AND decided_at IS NOT NULL AND decided_by_user_id IS NOT NULL AND referral_reason IS NULL) OR (decision='REFERRED' AND decided_at IS NOT NULL AND decided_by_user_id IS NOT NULL AND referral_reason IS NOT NULL AND btrim(referral_reason)<>'')));
CREATE OR REPLACE FUNCTION request_case_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM establishments e WHERE e.id=NEW.establishment_id AND e.company_id<>NEW.company_id) THEN RAISE EXCEPTION 'establishment company mismatch'; END IF; IF NEW.status='PENDING_ASSIGNMENT' AND NOT EXISTS(SELECT 1 FROM request_documents WHERE request_id=NEW.id AND document_type='AUTHORIZATION_LETTER' AND status='VALID' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'valid authorization letter required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER company_requests_guard BEFORE INSERT OR UPDATE ON company_requests FOR EACH ROW EXECUTE FUNCTION request_case_guard();
CREATE TABLE request_status_transitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES company_requests(id) ON DELETE RESTRICT,from_status request_status,to_status request_status NOT NULL,reason text,changed_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE case_status_transitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES cases(id) ON DELETE RESTRICT,from_status case_status,to_status case_status NOT NULL,reason text,changed_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE OR REPLACE FUNCTION case_state_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN IF (NEW.origin IN('COMPANY_REQUEST','INSTITUTIONAL_PROGRAM') AND NEW.status<>'PENDING_ASSIGNMENT') OR (NEW.origin IN('HEALTH_ALERT','COMPLAINT') AND NEW.status<>'PENDING_REVIEW') THEN RAISE EXCEPTION 'invalid initial case status'; END IF; RETURN NEW; END IF; IF NEW.status IS DISTINCT FROM OLD.status AND NOT ((OLD.status='PENDING_REVIEW' AND NEW.status IN('PENDING_ASSIGNMENT','NO_ACTION','REFERRED')) OR (OLD.status='PENDING_ASSIGNMENT' AND NEW.status='CLOSED')) THEN RAISE EXCEPTION 'invalid case transition'; END IF; RETURN NEW; END $$;
CREATE TRIGGER cases_state_guard BEFORE INSERT OR UPDATE ON cases FOR EACH ROW EXECUTE FUNCTION case_state_guard();
CREATE OR REPLACE FUNCTION origin_integrity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE cid uuid; o case_origin; n_alert integer; n_complaint integer; n_program integer; r uuid; BEGIN IF TG_TABLE_NAME='cases' THEN cid:=NEW.id; ELSE cid:=((CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END)->>'case_id')::uuid; END IF; SELECT origin,request_id INTO o,r FROM cases WHERE id=cid; IF o IS NULL THEN RETURN NULL; END IF; SELECT count(*) INTO n_alert FROM health_alerts WHERE case_id=cid; SELECT count(*) INTO n_complaint FROM complaints WHERE case_id=cid; SELECT count(*) INTO n_program FROM institutional_program_cases WHERE case_id=cid; IF (o='COMPANY_REQUEST' AND (r IS NULL OR n_alert+n_complaint+n_program<>0)) OR (o='INSTITUTIONAL_PROGRAM' AND (r IS NOT NULL OR n_program<>1 OR n_alert+n_complaint<>0)) OR (o='HEALTH_ALERT' AND (r IS NOT NULL OR n_alert<>1 OR n_complaint+n_program<>0)) OR (o='COMPLAINT' AND (r IS NOT NULL OR n_complaint<>1 OR n_alert+n_program<>0)) THEN RAISE EXCEPTION 'case origin source mismatch'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER cases_origin_guard AFTER INSERT OR UPDATE ON cases DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION origin_integrity_guard();
CREATE CONSTRAINT TRIGGER alerts_origin_guard AFTER INSERT OR UPDATE OR DELETE ON health_alerts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION origin_integrity_guard();
CREATE CONSTRAINT TRIGGER complaints_origin_guard AFTER INSERT OR UPDATE OR DELETE ON complaints DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION origin_integrity_guard();
CREATE CONSTRAINT TRIGGER programs_origin_guard AFTER INSERT OR UPDATE OR DELETE ON institutional_program_cases DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION origin_integrity_guard();
CREATE OR REPLACE FUNCTION record_request_status_transition() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO request_status_transitions(request_id,from_status,to_status) VALUES(NEW.id,OLD.status,NEW.status); END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION record_case_status_transition() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO case_status_transitions(case_id,from_status,to_status,reason) VALUES(NEW.id,OLD.status,NEW.status,CASE WHEN NEW.status IN('NO_ACTION','REFERRED','CLOSED') THEN NEW.closed_reason ELSE NULL END); END IF; RETURN NEW; END $$;
CREATE TRIGGER company_requests_status_history AFTER UPDATE ON company_requests FOR EACH ROW EXECUTE FUNCTION record_request_status_transition();
CREATE TRIGGER cases_status_history AFTER UPDATE ON cases FOR EACH ROW EXECUTE FUNCTION record_case_status_transition();
CREATE OR REPLACE FUNCTION sync_case_from_health_alert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.decision='PROCEEDS' THEN UPDATE cases SET status='PENDING_ASSIGNMENT' WHERE id=NEW.case_id AND status='PENDING_REVIEW'; ELSIF NEW.decision='NOT_PROCEEDS' THEN UPDATE cases SET status='NO_ACTION',closed_at=clock_timestamp(),closed_reason=COALESCE(NULLIF(btrim(NEW.decision_reason),''),'Alerta no procede') WHERE id=NEW.case_id AND status='PENDING_REVIEW'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION sync_case_from_complaint() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.decision='PROCEEDS' THEN UPDATE cases SET status='PENDING_ASSIGNMENT' WHERE id=NEW.case_id AND status='PENDING_REVIEW'; ELSIF NEW.decision='NOT_PROCEEDS' THEN UPDATE cases SET status='NO_ACTION',closed_at=clock_timestamp(),closed_reason='Denuncia no procede' WHERE id=NEW.case_id AND status='PENDING_REVIEW'; ELSIF NEW.decision='REFERRED' THEN UPDATE cases SET status='REFERRED',closed_at=clock_timestamp(),closed_reason=NEW.referral_reason WHERE id=NEW.case_id AND status='PENDING_REVIEW'; END IF; RETURN NEW; END $$;
CREATE TRIGGER health_alerts_case_sync AFTER INSERT OR UPDATE ON health_alerts FOR EACH ROW EXECUTE FUNCTION sync_case_from_health_alert();
CREATE TRIGGER complaints_case_sync AFTER INSERT OR UPDATE ON complaints FOR EACH ROW EXECUTE FUNCTION sync_case_from_complaint();
CREATE TRIGGER company_requests_version BEFORE UPDATE ON company_requests FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_version();
CREATE TRIGGER request_documents_version BEFORE UPDATE ON request_documents FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_version();
CREATE TRIGGER request_contacts_version BEFORE UPDATE ON request_contacts FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_version();
CREATE TRIGGER cases_version BEFORE UPDATE ON cases FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_version();
